@Service
public class OrderProcessingService {

    private final OrderRepository orderRepository;
    private final BillingService billingService;

    public OrderProcessingService(OrderRepository orderRepository, BillingService billingService) {
        this.orderRepository = orderRepository;
        this.billingService = billingService;
    }

    @Transactional(propagation = Propagation.REQUIRED, rollbackFor = Exception.class)
    public void completeOrder(OrderDto orderDto) {
        Order order = orderRepository.save(new Order(orderDto));
        // Invoking another service method within the same boundary
        billingService.processPayment(order.getId(), orderDto.getPaymentInfo());
    }
}
